-- Christmas SEO factory: locale/cluster columns on seo_pages + cluster seed.
-- Additive. No checkout activation. Public read stays RLS is_active.

begin;

alter table public.seo_pages
  add column if not exists locale text not null default 'en';

alter table public.seo_pages
  add column if not exists cluster text;

alter table public.seo_pages
  add column if not exists canonical_path text;

alter table public.seo_pages
  add column if not exists sections jsonb not null default '[]'::jsonb;

alter table public.seo_pages
  add column if not exists cta_href text;

alter table public.seo_pages
  drop constraint if exists seo_pages_page_type_slug_key;

alter table public.seo_pages
  drop constraint if exists seo_pages_page_type_slug_locale_key;

alter table public.seo_pages
  add constraint seo_pages_page_type_slug_locale_key unique (page_type, slug, locale);

alter table public.seo_pages
  drop constraint if exists seo_pages_locale_chk;

alter table public.seo_pages
  add constraint seo_pages_locale_chk check (locale in ('en', 'ro'));

alter table public.seo_pages
  drop constraint if exists seo_pages_cluster_chk;

alter table public.seo_pages
  add constraint seo_pages_cluster_chk check (
    cluster is null
    or cluster in ('gifts-for', 'messages-for', 'messages-intent')
  );

create index if not exists seo_pages_cluster_locale_idx
  on public.seo_pages (cluster, locale)
  where is_active and cluster is not null;

create unique index if not exists seo_pages_canonical_locale_uidx
  on public.seo_pages (canonical_path, locale)
  where canonical_path is not null;

commit;

