    '[{"heading":"Ciorne pe care le poți trimite de pe adresa de serviciu","body":"Dacă n-ai pune-o într-un ticket, n-o pune pe o felicitare de sărbători.","items":[{"title":"Echipă","text":"Mulțumesc pentru anul pus în munca asta. Sper ca pauza să fie pauză. Sărbători fericite."},{"title":"Client","text":"Mulțumim pentru încrederea din anul ăsta. Odihnă și un ianuarie așezat — fără cereri atașate."},{"title":"Furnizor","text":"Anul a fost mai ușor pentru că erați de cealaltă parte a thread-ului. Bucurați-vă de liniște."},{"title":"BCC mare","text":"Mulțumim tuturor celor cu care am construit în 2026. Zile blânde și un start curat."},{"title":"Notă de manager","text":"Nu recapitulăm metricile aici. Spun mulțumesc și mă refer la timpul pe care l-ați acoperit."}]},{"heading":"Nu amesteca cu romantism sau roast","body":"Fără provocări cu alcool, fără comentarii despre familii, fără poze cu copii dacă un părinte din echipă n-a cerut. Fără „sunteți ca o familie” către oameni care-ți raportează."},{"heading":"Generează pe profesional","body":"Apoi deschide paginile de coleg sau client pentru exemple țintite spre birou sau spre factură. Urările scurte ajută când lista e lungă. Cadourile pentru colegi există dacă cultura cere și un obiect."}]'::jsonb,
